contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmt: amount to send to C using its Deposit/receive path
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // Observe initial recorded balance and contract ETH
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        // Perform deposit by calling the explicit Deposit function on C and sending ETH
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Observe after-deposit values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterEth = address(c).balance;

        // The deposit must not decrease the recorded balance or contract ETH,
        // and the increase in recorded balance must equal the increase in contract ETH.
        // That is: afterRecorded >= beforeRecorded, afterEth >= beforeEth,
        // and (afterRecorded - beforeRecorded) == (afterEth - beforeEth).
        // Use only non-underflowing expressions in the assert by comparing via additions.
        assert(
            afterRecorded >= beforeRecorded
            && afterEth >= beforeEth
            && (beforeRecorded + (afterEth - beforeEth) == afterRecorded)
        );
    }

    // allow receiving refunds forwarded by C during Collect (not used here but harmless)
    receive() external payable {}
}

